/* common.mpvo.updateMasterMpVoVocDsUserInfo */
	UPDATE KEPAVCDT SET
	    DS_USER_ID = #{st_ds_user_id},
	    DS_DEPT = #{st_ds_dept_id},
	    DS_CHANGE_FLAG = 'Y',
	    DS_CHANGE_DATE = SYSDATE
	WHERE BUYER = #{st_buyer}
	    AND VC_NO = #{st_vc_no}
	    AND REQ_USER_ID = #{st_req_user_id}


/* common.mpvo.updateMasterMpVoVocProgressStateFbChangePop */
	UPDATE KEPAVCDT SET 
	    CLAIM_MASTER = #{st_claim_master},
	    CLAIM_TYPE = #{st_claim_type}


			, CLAIM_GRADE = #{st_claim_grade}	


	WHERE VC_NO = #{st_vc_no}
	    AND REQ_USER_ID = #{st_req_user_id}
	    AND BUYER = #{st_buyer}


/* common.mpvo.insertMpVoVocRevPop */
	UPDATE KEP_VOC_REVISION A
	SET A.REQ_USER_ID = #{st_user_id},
	    A.REQ_DATE = SYSDATE,
	    A.REQ_NOTE = #{st_re_req_note}
	WHERE A.VC_NO = #{st_vc_no}
	AND A.REVISION = #{st_revision}


/* common.mpvo.updateMasterMpVoVocProgressPCPop */
	UPDATE KEPAVCDT SET
		DS_REMARK_A = #{st_ds_remark_1},
		DS_CHANGE_FLAG = #{st_ds_change_flag},
	    DS_CHANGE_DATE = DECODE(#{st_ds_change_flag},'Y',SYSDATE,''),
	    IMPUTE_TYPE = #{st_impute_type},
	    IMPUTE_AGENT = #{st_agent_code},
	    DS_IMAGE_KEY = #{st_image_key2},


			CLAIM_GRADE = #{st_claim_grade},	


	    CLAIM_MASTER = #{st_claim_master},
	    CLAIM_TYPE = #{st_claim_type}
	WHERE BUYER = #{st_buyer}
	    AND VC_NO = #{st_vc_no}
	    AND REQ_USER_ID = #{st_req_user_id}
	    AND RECV_FLAG <> 'FB'
